#include "SM64SystemCore.hpp"
#include <algorithm>
#include <fstream>
#include <iomanip>
#include <sstream>
namespace sm64 { static uint16_t be(const uint8_t*p){return uint16_t((p[0]<<8)|p[1]);} uint16_t Core::sum(const uint8_t*p,size_t n){uint16_t s=0;for(size_t i=0;i<n-2;i++)s=uint16_t(s+p[i]);return s;}void Core::fix(uint8_t*p,size_t n){p[n-4]=0x44;p[n-3]=0x41;auto s=sum(p,n);p[n-2]=s>>8;p[n-1]=s;}
Core::Core(){data_.fill(0);normalize();base_=data_;}void Core::set(size_t i,uint8_t v){data_.at(i)=v;}void Core::setMirrored(int s,size_t r,uint8_t v){set(P.at(s)+r,v);set(B.at(s)+r,v);}Report Core::validate()const{Report r;r.valid=true;for(int i=0;i<8;i++){size_t o=(i%2?B:P)[i/2];auto&q=r.slots[i];q.magic=data_[o+52]==0x44&&data_[o+53]==0x41;q.stored=be(&data_[o+54]);q.computed=sum(&data_[o],Block);q.checksum=q.stored==q.computed;r.valid&=q.magic&&q.checksum;}for(int i=0;i<2;i++){size_t o=0x1C0+i*0x20;auto&q=r.menu[i];q.magic=data_[o+28]==0x44&&data_[o+29]==0x41;q.stored=be(&data_[o+30]);q.computed=sum(&data_[o],32);q.checksum=q.stored==q.computed;r.valid&=q.magic&&q.checksum;}return r;}
void Core::normalize(){for(auto o:P)fix(&data_[o],56);for(auto o:B)fix(&data_[o],56);fix(&data_[0x1C0],32);fix(&data_[0x1E0],32);}std::vector<std::string> Core::repair(){std::vector<std::string>a;auto good=[](const uint8_t*p,size_t n){return p[n-4]==0x44&&p[n-3]==0x41&&be(p+n-2)==Core::sum(p,n);};for(int i=0;i<4;i++){bool p=good(&data_[P[i]],56),b=good(&data_[B[i]],56);if(!p&&b){std::copy_n(&data_[B[i]],56,&data_[P[i]]);a.push_back("Restored primary slot "+std::string(1,'A'+i));}else if(p&&!b){std::copy_n(&data_[P[i]],56,&data_[B[i]]);a.push_back("Restored backup slot "+std::string(1,'A'+i));}}return a;}
bool Core::load(const std::filesystem::path&p,bool ar,std::string&e){std::ifstream f(p,std::ios::binary);if(!f){e="Cannot open file";return false;}f.read((char*)data_.data(),512);if(f.gcount()!=512||f.peek()!=std::ifstream::traits_type::eof()){e="Input must be exactly 512 bytes";return false;}auto score=[&](const Bytes&x){Core c;c.data_=x;auto r=c.validate();int n=0;for(auto&s:r.slots)n+=s.magic&&s.checksum;return n;};Bytes best=data_;int top=score(best);for(int mode=1;mode<=2;mode++){Bytes x=data_;if(mode==1)for(size_t i=0;i<512;i+=2)std::swap(x[i],x[i+1]);else for(size_t i=0;i<512;i+=4){std::swap(x[i],x[i+3]);std::swap(x[i+1],x[i+2]);}int n=score(x);if(n>top){best=x;top=n;}}data_=best;base_=data_;if(ar)repair();return true;}
bool Core::write(const std::filesystem::path&p,const std::vector<uint8_t>&d,std::string&e){auto t=p;t+=".tmp";{std::ofstream f(t,std::ios::binary);if(!f){e="Cannot create output";return false;}f.write((const char*)d.data(),d.size());if(!f){e="Write failed";return false;}}std::error_code ec;std::filesystem::rename(t,p,ec);if(ec){std::filesystem::remove(p,ec);ec.clear();std::filesystem::rename(t,p,ec);}if(ec){e=ec.message();return false;}return true;}bool Core::save(const std::filesystem::path&p,std::string&e){normalize();std::vector<uint8_t>d(data_.begin(),data_.end());if(!write(p,d,e))return false;base_=data_;return true;}bool Core::exportFile(const std::filesystem::path&p,Profile x,std::string&e){normalize();size_t n=x==Profile::SRA?32768:512;std::vector<uint8_t>d(n,x==Profile::SRA?0xFF:0);std::copy(data_.begin(),data_.end(),d.begin());if(x==Profile::SRA)for(size_t i=0;i<512;i+=2)std::swap(d[i],d[i+1]);return write(p,d,e);}std::string Core::gameShark(uint32_t addr,bool word,bool all)const{if(addr<0x80000000||addr>0x807FFFFF)return "# Invalid RDRAM address\n";std::ostringstream s;s<<"# Verify this buffer address for your exact ROM revision.\n"<<std::uppercase<<std::hex<<std::setfill('0');for(size_t i=0;i<512;){if(!all&&data_[i]==base_[i]){i++;continue;}uint32_t a=(addr+i)&0xFFFFFF;if(word&&i%2==0&&i+1<512&&(all||data_[i+1]!=base_[i+1])){s<<"81"<<std::setw(6)<<a<<" "<<std::setw(4)<<((data_[i]<<8)|data_[i+1])<<"\n";i+=2;}else{s<<"80"<<std::setw(6)<<a<<" 00"<<std::setw(2)<<unsigned(data_[i])<<"\n";i++;}}return s.str();}}
